import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"27、【頤】 震下艮上","description":"溫公易說 - 27、【頤】 震下艮上","frontmatter":{"title":"27、【頤】 震下艮上","description":"溫公易說 - 27、【頤】 震下艮上"},"headers":[],"relativePath":"classics/wengong/028.md","filePath":"classics/wengong/028.md"}'),l={name:"classics/wengong/028.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_27、【頤】-震下艮上" tabindex="-1">27、【頤】 震下艮上 <a class="header-anchor" href="#_27、【頤】-震下艮上" aria-label="Permalink to “27、【頤】 震下艮上”">​</a></h1><h3 id="彖曰-頤-貞吉-養正則吉也。觀頤-觀其所養也。自求口實-觀其自養也。天地養萬物-聖人養賢以及萬民。頤之時大矣哉。" tabindex="-1">彖曰：頤，貞吉，養正則吉也。觀頤，觀其所養也。自求口實，觀其自養也。天地養萬物，聖人養賢以及萬民。頤之時大矣哉。 <a class="header-anchor" href="#彖曰-頤-貞吉-養正則吉也。觀頤-觀其所養也。自求口實-觀其自養也。天地養萬物-聖人養賢以及萬民。頤之時大矣哉。" aria-label="Permalink to “彖曰：頤，貞吉，養正則吉也。觀頤，觀其所養也。自求口實，觀其自養也。天地養萬物，聖人養賢以及萬民。頤之時大矣哉。”">​</a></h3><p>凡萬物有者為陽，無者為陰。日光之所灼者為陽，所不灼者為陰。和氣之所煦者為陽，所不煦者為陰。聖人之於仁義，猶是也。愛養萬物謂之仁，其所不愛不養謂之義。義者，裁仁以就宜者也。或曰：聖人之仁無不及也，而有不愛不養乎？曰：暴亂而為物害者，聖人所不得而愛養也。聖人豈樂殺哉？何謂觀其所養？其人賢則其所養必賢也，其人不肖則所養必不肖也。何謂觀其自養？取於人以義，自奉養以禮，斯賢也。取於人無度，自奉養無節，斯不肖也。故富視其所與，貧視其所取，窮視其所主，達視其所舉，足以知其為人矣。</p><h3 id="象曰-山下有雷-頤。君子以慎言語-節飲食。" tabindex="-1">象曰：山下有雷，頤。君子以慎言語，節飲食。 <a class="header-anchor" href="#象曰-山下有雷-頤。君子以慎言語-節飲食。" aria-label="Permalink to “象曰：山下有雷，頤。君子以慎言語，節飲食。”">​</a></h3><h3 id="初九-捨爾靈觀-我朵頤-兇-象曰-觀我朵頤-亦不足貴也。" tabindex="-1">初九：捨爾靈觀，我朵頤，兇 象曰：觀我朵頤，亦不足貴也。 <a class="header-anchor" href="#初九-捨爾靈觀-我朵頤-兇-象曰-觀我朵頤-亦不足貴也。" aria-label="Permalink to “初九：捨爾靈觀，我朵頤，兇 象曰：觀我朵頤，亦不足貴也。”">​</a></h3><h3 id="六二-顛頤-拂經於丘頤-徵兇-象曰-六二徵兇-行失類也。" tabindex="-1">六二：顛頤，拂經於丘頤，徵兇 象曰：六二徵兇，行失類也。 <a class="header-anchor" href="#六二-顛頤-拂經於丘頤-徵兇-象曰-六二徵兇-行失類也。" aria-label="Permalink to “六二：顛頤，拂經於丘頤，徵兇 象曰：六二徵兇，行失類也。”">​</a></h3><h3 id="六三-拂頤-貞兇-十年勿用-無攸利-象曰-十年勿用-道大悖也。" tabindex="-1">六三：拂頤，貞兇，十年勿用，無攸利 象曰：十年勿用，道大悖也。 <a class="header-anchor" href="#六三-拂頤-貞兇-十年勿用-無攸利-象曰-十年勿用-道大悖也。" aria-label="Permalink to “六三：拂頤，貞兇，十年勿用，無攸利 象曰：十年勿用，道大悖也。”">​</a></h3><h3 id="六四-顚頤-吉。虎視眈眈-其欲逐逐-無咎-象曰-顛頤之吉-上施光也。" tabindex="-1">六四：顚頤，吉。虎視眈眈，其欲逐逐，無咎 象曰：顛頤之吉，上施光也。 <a class="header-anchor" href="#六四-顚頤-吉。虎視眈眈-其欲逐逐-無咎-象曰-顛頤之吉-上施光也。" aria-label="Permalink to “六四：顚頤，吉。虎視眈眈，其欲逐逐，無咎 象曰：顛頤之吉，上施光也。”">​</a></h3><h3 id="六五-拂經-居貞吉-不可涉大川-象曰-居貞之吉-順以從上也。" tabindex="-1">六五：拂經，居貞吉，不可涉大川 象曰：居貞之吉，順以從上也。 <a class="header-anchor" href="#六五-拂經-居貞吉-不可涉大川-象曰-居貞之吉-順以從上也。" aria-label="Permalink to “六五：拂經，居貞吉，不可涉大川 象曰：居貞之吉，順以從上也。”">​</a></h3><h3 id="上九-由頤-厲-吉-利涉大川-象曰-由頤厲吉-大有慶也。" tabindex="-1">上九：由頤，厲，吉，利涉大川 象曰：由頤厲吉，大有慶也。 <a class="header-anchor" href="#上九-由頤-厲-吉-利涉大川-象曰-由頤厲吉-大有慶也。" aria-label="Permalink to “上九：由頤，厲，吉，利涉大川 象曰：由頤厲吉，大有慶也。”">​</a></h3>',10)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
